SOURCE_CLAIM_JSON: {"title":"Putin's Friend Receives State Funding to Combat Corruption","publisher":"OCCRP","publication_date":"2019-01-15","url":"https://www.occrp.org/en/news/putins-friend-receives-state-funding-to-combat-corruption","claim":"OCCRP reported that Arkady Rotenberg, a childhood friend of Putin, won a state contract for anti-corruption training, and that Putin had earlier created a state body that handed Rotenberg control over part of the vodka market.","locator":"lines 32-52","source_type":"NGO","source_confidence":"medium_high","source_confidence_reason":"Older investigative reporting with concrete state-contract and ownership details that are directly relevant to patronage patterns.","final_evidence_use":"final_evidence","period_fit":"Pre-2022 pattern evidence relevant to the 2022 ruler-period.","ruler_attribution":"Indirect but strong: the item concerns a childhood friend of Putin receiving state benefit through proximity to Putin.","contrary_evidence":[],"lenses":["7B.5","7B.9"]}
SOURCE_CLAIM_JSON: {"title":"Cars, Connections, and Contracts in Putin’s Russia","publisher":"OCCRP","publication_date":"2016-03-31","url":"https://www.occrp.org/en/investigation/cars-connections-and-contracts-in-putins-russia","claim":"OCCRP reported that companies with ties to Russia’s security and prosecutorial elite won large state contracts and that watchdogs described this as a common pattern where taxpayers’ money flows to those close to the elite.","locator":"lines 51-55","source_type":"NGO","source_confidence":"medium_high","source_confidence_reason":"Documentary investigative reporting showing a recurring conflict-of-interest pattern in the Putin-era state.","final_evidence_use":"final_evidence","period_fit":"Pre-2022 pattern evidence relevant to the 2022 ruler-period.","ruler_attribution":"Indirect but strong: the article situates the contract pattern inside the Putin-era elite network.","contrary_evidence":[],"lenses":["7B.5","7B.9"]}
SOURCE_CLAIM_JSON: {"title":"Leaked Emails Reveal How Putin’s Friends Dodged Sanctions With Help of Western Enablers","publisher":"OCCRP","publication_date":"2022-09-15","url":"https://www.occrp.org/en/project/the-rotenberg-files/leaked-emails-reveal-how-putins-friends-dodged-sanctions-with-help-of-western-enablers","claim":"OCCRP published leaked emails showing a memo labeled Objective: Clear Sanctions that described a restructuring plan to preserve the Rotenberg brothers’ share in Helsinki Halli.","locator":"lines 84-88","source_type":"NGO","source_confidence":"medium_high","source_confidence_reason":"Direct documentary leak with explicit sanctions-evasion planning.","final_evidence_use":"final_evidence","period_fit":"Directly within the 2022 target year, though the conduct is rooted in earlier sanctions circumvention.","ruler_attribution":"Indirect but strong: the brothers are long-time Putin associates, and the concealment behavior is tied to Putin’s orbit.","contrary_evidence":["The source relies on leaked emails and describes an alleged restructuring plan rather than a judicial finding."],"lenses":["7B.7","7B.9"]}
SOURCE_CLAIM_JSON: {"title":"Treasury Sanctions Russian Officials, Members Of The Russian Leadership’s Inner Circle, And An Entity For Involvement In The Situation In Ukraine","publisher":"U.S. Department of the Treasury","publication_date":"2014-03-20","url":"https://home.treasury.gov/news/press-releases/jl23331","claim":"Treasury said Putin has investments in Gunvor, that the Rotenberg brothers received about $7 billion in contracts awarded by Putin, and that Yuri Kovalchuk was Putin’s personal banker and cashiers-like advisor.","locator":"lines 648-653","source_type":"official","source_confidence":"high","source_confidence_reason":"Official sanctions notice with unusually explicit descriptions of the Putin inner circle’s financial and contract links.","final_evidence_use":"final_evidence","period_fit":"Pre-2022 pattern evidence relevant to the 2022 ruler-period.","ruler_attribution":"Indirect but strong: the notice directly ties financial benefit, contracts and access to Putin’s personal circle.","contrary_evidence":["This is a sanctions finding, not a criminal verdict; the government notice is itself an accusation-based instrument."],"lenses":["7B.3","7B.4","7B.5","7B.9"]}
SOURCE_CLAIM_JSON: {"title":"Russia: Fraud charges against Aleksei Navalny are arbitrary and politically motivated","publisher":"Amnesty International","publication_date":"2022-03-11","url":"https://www.amnesty.org/en/documents/eur46/5329/2022/en/","claim":"Amnesty concluded that the new fraud charges against Navalny were politically motivated and aimed to criminalize his anti-corruption and political activism.","locator":"lines 67-68","source_type":"NGO","source_confidence":"high","source_confidence_reason":"Direct human-rights assessment of a politically sensitive prosecution closely tied to anti-corruption scrutiny of the Putin system.","final_evidence_use":"final_evidence","period_fit":"Directly within the 2022 target year.","ruler_attribution":"Strong indirect attribution: the prosecution targeted Navalny’s anti-corruption work against Putin-linked elites, but the item stops short of proving Putin personally ordered the charge.","contrary_evidence":["The Russian authorities presented the case as a legal fraud prosecution."],"lenses":["7B.6","7B.7","7B.10"]}
SOURCE_CLAIM_JSON: {"title":"Russia: One year after jailing, Aleksei Navalny and his associates in a living hell","publisher":"Amnesty International","publication_date":"2022-01-17","url":"https://www.amnesty.org/en/latest/news/2022/01/russia-one-year-after-jailing-aleksei-navalny-and-his-associates-in-a-living-hell/","claim":"Amnesty said Russian authorities dismantled Navalny’s Anti-Corruption Foundation, labelled his organizations extremist, blocked their websites, and criminalized their activities.","locator":"lines 64-71","source_type":"NGO","source_confidence":"high","source_confidence_reason":"Direct human-rights reporting on state suppression of an anti-corruption movement with clear, traceable dates and actions.","final_evidence_use":"final_evidence","period_fit":"Directly within the 2022 target year and immediately prior to the invasion period.","ruler_attribution":"Strong indirect attribution: the crackdown targeted the leading anti-corruption network challenging Putin’s circle, but the item does not itself prove direct personal orders.","contrary_evidence":[],"lenses":["7B.6","7B.7","7B.10"]}
