SOURCE_CLAIM_JSON: {"title":"Central bank says 28 February hike and capital controls helped support stable functioning of financial system","publisher":"Bank of Russia","publication_date":"2022-03-18","url":"https://www.cbr.ru/eng/press/pr?file=18032022_133000key_eng.htm","claim":"The central bank said the late-February rate hike and capital controls helped support the stable functioning of the financial system.","locator":"press release","source_type":"official","source_confidence":"high","source_confidence_reason":"Primary official statement directly linking policy tools to observed stabilization.","final_evidence_use":"final_evidence","period_fit":"directly in 2022","ruler_attribution":"mostly indirect to Putin because the bank carried out the stabilization, though it operated inside his regime's wartime policy framework.","contrary_evidence":["Stabilization was defensive and partial, not proof of broad economic success."],"lenses":["8B.5","8B.6","8B.8","8B.9","8B.10"]}
